function window() {
  const p = new Intl.DateTimeFormat("en-CA-u-ca-iso8601", {
      timeZone: "America/Los_Angeles",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    }).formatToParts(new Date()),
    v = Object.fromEntries(p.map((x) => [x.type, x.value])),
    today = Date.UTC(Number(v.year), Number(v.month) - 1, Number(v.day)),
    date = (n) => new Date(today - n * 86400000).toISOString().slice(0, 10);
  return { startDate: date(7), endDate: date(1) };
}

return [{ json: { ...window(), siteUrl: "https://example.com/" } }];

function summarize({ rows, startDate, endDate }) {
  if (!Array.isArray(rows) || rows.length > 10) throw Error("Invalid Search Console rows");
  let lines = [];
  for (const [i, r] of rows.entries()) {
    if (
      !Array.isArray(r.keys) ||
      r.keys.length !== 1 ||
      typeof r.keys[0] !== "string" ||
      !["clicks", "impressions", "ctr", "position"].every(
        (k) => typeof r[k] === "number" && Number.isFinite(r[k]),
      )
    )
      throw Error("Invalid Search Console row");
    const query = r.keys[0].replace(/[\r\n]+/g, " ");
    lines.push(
      `${i + 1}. ${query} - Clicks: ${r.clicks}, Impressions: ${r.impressions}, CTR: ${r.ctr.toFixed(2)}, Position: ${r.position.toFixed(2)}`,
    );
  }
  return {
    text: `Top 10 Search Queries (${startDate} through ${endDate}, Pacific Time):\n\n${lines.length ? lines.join("\n") : "No data returned."}`,
  };
}

const w = $("Set the reporting dates").first().json;
return [
  {
    json: summarize({
      rows: $input.first().json.rows ?? [],
      startDate: w.startDate,
      endDate: w.endDate,
    }),
  },
];
